package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDivide_NullArgument() {
        Complex c = new Complex(1.0, 1.0);
        try {
            c.divide(null);
            fail("Expected NullArgumentException");
        } catch (NullArgumentException e) {
            // Success
        }
    }

    @Test
    public void testDivide_NaN_Result() {
        Complex c1 = Complex.NaN;
        Complex c2 = new Complex(1.0, 1.0);
        assertTrue(c1.divide(c2).isNaN());

        Complex c3 = new Complex(1.0, 1.0);
        Complex c4 = Complex.NaN;
        assertTrue(c3.divide(c4).isNaN());
    }

    @Test
    public void testDivide_DivisorIsZero_ResultNaN() {
        // if (divisor.isZero) { return isZero ? NaN : INF; }
        // Case: isZero is true
        Complex c1 = Complex.ZERO;
        Complex c2 = Complex.ZERO;
        assertTrue(c1.divide(c2).isNaN());
    }

    @Test
    public void testDivide_DivisorIsZero_ResultINF() {
        // Case: isZero is false
        Complex c1 = new Complex(1.0, 1.0);
        Complex c2 = Complex.ZERO;
        assertTrue(c1.divide(c2).isInfinite());
    }

    @Test
    public void testDivide_DivisorIsInfinite_ResultZero() {
        // if (divisor.isInfinite() && !isInfinite()) { return ZERO; }
        Complex c1 = new Complex(5.0, 5.0);
        Complex c2 = Complex.INF;
        assertEquals(Complex.ZERO, c1.divide(c2));
    }

    @Test
    public void testDivide_DivisorIsInfinite_ResultInfinite() {
        // if (divisor.isInfinite() && !isInfinite()) is false if isInfinite() is true
        Complex c1 = Complex.INF;
        Complex c2 = Complex.INF;
        // When both are infinite, it falls through to the calculation logic
        // which generally results in NaN or a value depending on the implementation of division
        assertFalse(c1.divide(c2).equals(Complex.ZERO));
    }

    @Test
    public void testDivide_Branch_AbsC_LessThan_AbsD() {
        // if (FastMath.abs(c) < FastMath.abs(d))
        // Let c = 1, d = 2
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(1.0, 2.0);
        // (1+2i)/(1+2i) = 1
        Complex result = c1.divide(c2);
        assertEquals(1.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);

        // Specific values to trigger the q = c/d branch
        // c=1, d=10 -> q=0.1. denominator = 1*0.1 + 10 = 10.1
        // real_new = (1*0.1 + 2)/10.1 = 2.1/10.1
        // imag_new = (2*0.1 + 1)/10.1 = 1.2/10.1
        Complex c3 = new Complex(1.0, 2.0);
        Complex c4 = new Complex(1.0, 10.0);
        Complex res = c3.divide(c4);
        assertEquals(2.1/10.1, res.getReal(), EPSILON);
        assertEquals(1.2/10.1, res.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_Branch_AbsC_GreaterThanOrEqual_AbsD() {
        // if (FastMath.abs(c) >= FastMath.abs(d))
        // Let c = 2, d = 1
        Complex c1 = new Complex(2.0, 1.0);
        Complex c2 = new Complex(2.0, 1.0);
        // (2+i)/(2+i) = 1
        Complex result = c1.divide(c2);
        assertEquals(1.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);

        // Specific values to trigger the q = d/c branch
        // c=10, d=1 -> q=0.1. denominator = 1*0.1 + 10 = 10.1
        // real_new = (1*0.1 + 10)/10.1 = 10.1/10.1 = 1
        // imag_new = (1 - 10*0.1)/10.1 = 0
        Complex c3 = new Complex(10.0, 1.0);
        Complex c4 = new Complex(10.0, 1.0);
        Complex res = c3.divide(c4);
        assertEquals(1.0, res.getReal(), EPSILON);
        assertEquals(0.0, res.getImaginary(), EPSILON);
    }

    @Test
    public void testDivide_StandardDivision() {
        // (1 + 2i) / (3 + 4i)
        // = [(1*3 + 2*4) / (3^2 + 4^2)] + i[(2*3 - 1*4) / (3^2 + 4^2)]
        // = [11/25] + i[2/25] = 0.44 + 0.08i
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(3.0, 4.0);
        Complex result = c1.divide(c2);
        assertEquals(0.44, result.getReal(), EPSILON);
        assertEquals(0.08, result.getImaginary(), EPSILON);
    }
}
